mapper.update:
update skiller
name = #{name}, phone = #{phone}, student_no = #{studentNo}, campus = #{campus}, college = #{college}, audit_status = #{auditStatus}, runner_level = #{runnerLevel}, daily_order_limit = #{dailyOrderLimit}, completed_orders = #{completedOrders}, score = #{score}, credit_score = #{creditScore}, skill_level = #{skillLevel}, status = #{status}, update_time = now()
where id = #{id}

mapper.select:
select * from skiller

    and name like concat('%', #{name}, '%')
    and campus like concat('%', #{campus}, '%')
    and audit_status = #{auditStatus}
    and status = #{status}

order by score desc, completed_orders desc
